// spi_item.sv - generated by uvm_full_tb_generator.py, filled in with SPI protocol fields
//   One item = one frame: everything between CS_n going low and going high.
class spi_item extends uvm_sequence_item;

  // From a sequence to the slave driver: bytes to return on MISO in the next frame
  rand bit [7:0] resp_bytes[];

  // Filled in by the monitor
  bit [7:0]      mosi_bytes[$];   // SoC -> slave (written data)
  bit [7:0]      miso_bytes[$];   // slave -> SoC (readback data)
  int unsigned   frame_no;

  constraint c_resp { resp_bytes.size() inside {[1:16]}; }

  `uvm_object_utils_begin(spi_item)
    `uvm_field_array_int(resp_bytes, UVM_ALL_ON | UVM_HEX)
    `uvm_field_queue_int(mosi_bytes, UVM_ALL_ON | UVM_HEX)
    `uvm_field_queue_int(miso_bytes, UVM_ALL_ON | UVM_HEX)
    `uvm_field_int      (frame_no,   UVM_ALL_ON | UVM_DEC)
  `uvm_object_utils_end

  function new(string name="spi_item"); super.new(name); endfunction

  static function string bytes2str(bit [7:0] q[$]);
    string s = "";
    foreach (q[i]) s = {s, $sformatf("%02h ", q[i])};
    return s;
  endfunction

  function string convert2string();
    return $sformatf("frame %0d: MOSI[%0d] = %s| MISO[%0d] = %s",
                     frame_no, mosi_bytes.size(), bytes2str(mosi_bytes),
                     miso_bytes.size(), bytes2str(miso_bytes));
  endfunction
endclass
